1554	/// Drives `DashboardChartSection`'s own AI narrative paragraph (spec-8-2) —
1555	/// a second, independent fetch from [DashboardCubit]'s own aggregate fetch
1556	/// (Boundaries/Never: "couple the two `Resource`s into one state object"),
1557	/// mirroring [DashboardCubit]'s exact shape: a DI `registerLazySingleton`,
1558	/// constructor-subscribed to [PendingEntryWriteTracker.confirmedWrites] so
1559	/// it recomputes on every entry write same as the aggregate, and [load] is
1560	/// generation-guarded the same way.
1561	///
1562	/// Deliberately never caches a previous [load] result across calls, same
1563	/// rationale [DashboardCubit] gives — every [load] re-emits
1564	/// [ResourceLoading] first.
1565	class DashboardNarrativeCubit extends Cubit<Resource<String>> {
1566	  DashboardNarrativeCubit(this._repository, this._tracker)
1567	    : super(const ResourceIdle()) {
1568	    _confirmedSubscription = _tracker.confirmedWrites.listen((_) => load());
1569	  }
1570	
1571	  final DashboardRepository _repository;
1572	  final PendingEntryWriteTracker _tracker;
1573	  late final StreamSubscription<({String tempId, Entry entry})>
1574	  _confirmedSubscription;
1575	
1576	  /// Same generation-guard convention [DashboardCubit]'s own `_generation`
1577	  /// uses — guards against a stale in-flight [load] call's result landing
1578	  /// after a newer one has already superseded it.
1579	  int _generation = 0;
1580	
1581	  /// Boundaries: "`queryParameters: {'period': 'all'}` — same fixed value
1582	  /// as `dashboard-aggregate-get`" — [load]'s one and only call to
1583	  /// [DashboardRepository.getNarrative] always passes this.
1584	  Future<void> load() async {
1585	    final generation = ++_generation;
1586	    emit(ResourceLoading());
1587	    final result = await _repository.getNarrative(period: 'all');
1588	    // Mirrors `DashboardCubit.load()`'s own guard: `close()` can race this
1589	    // awaited call, and a newer `load()` (constructor-triggered
1590	    // `confirmedWrites` event, a second screen open, or a retry tap) can
1591	    // have superseded this one while it was in flight.
1592	    if (isClosed || generation != _generation) {
1593	      return;
1594	    }
1595	    result.match(
1596	      (failure) => emit(ResourceError(failure)),
1597	      (text) => emit(ResourceData(text)),
1598	    );
1599	  }
1600	
1601	  @override
1602	  Future<void> close() async {
1603	    await _confirmedSubscription.cancel();
1604	    return super.close();
1605	  }
1606	}
